const db = new DatabaseSync('C:/Users/win/.cc-switch/cc-switch.db');

const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
console.log('TABLES:', tables.map(t => t.name).join(', '));

for (const t of tables) {
  const cols = db.prepare(`PRAGMA table_info(${t.name})`).all();
  console.log(`\n=== ${t.name} ===`);
  console.log(cols.map(c => c.name).join(', '));
}

// Try common provider table names
const candidates = tables.map(t => t.name).filter(n => /provider|claude|model/i.test(n));
for (const table of candidates.length ? candidates : tables.map(t => t.name)) {
  try {
    const rows = db.prepare(`SELECT * FROM ${table} LIMIT 3`).all();
    if (rows.length) {
      console.log(`\nSAMPLE ${table}:`, JSON.stringify(rows[0], null, 2).slice(0, 2000));
    }
  } catch (e) {}
}

// Search for hcai and gpt providers
for (const table of tables.map(t => t.name)) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all();
  for (const col of cols) {
    if (typeof col.name !== 'string') continue;
    try {
      const rows = db.prepare(
        `SELECT * FROM ${table} WHERE CAST(${col.name} AS TEXT) LIKE '%hcai%' OR CAST(${col.name} AS TEXT) LIKE '%gpt%' OR CAST(${col.name} AS TEXT) LIKE '%5.5%' OR CAST(${col.name} AS TEXT) LIKE '%hctopup%' LIMIT 20`
      ).all();
      if (rows.length) {
        console.log(`\nMATCH ${table}.${col.name}:`, JSON.stringify(rows, null, 2));
      }
    } catch (e) {}
  }
}

