# Configure Cursor BYOK -> HCAI (gpt-5.5 via OpenAI-compatible API)
# Safe to re-run. Close Cursor completely before running.

param(
    [string]$ApiKey,
    [string]$BaseUrl = 'https://ai.hctopup.com/v1'
)

$ErrorActionPreference = 'Stop'

function Get-HcaiApiKeyFromCcSwitch {
    $dbPath = Join-Path $env:USERPROFILE '.cc-switch\cc-switch.db'
    if (-not (Test-Path $dbPath)) { return $null }
    $nodeScript = @'
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync(process.argv[1]);
const row = db.prepare("SELECT settings_config FROM providers WHERE id = 'hcai-1780471653026' AND app_type = 'claude'").get();
if (!row) process.exit(2);
const cfg = JSON.parse(row.settings_config || '{}');
const key = cfg?.env?.ANTHROPIC_AUTH_TOKEN;
if (!key) process.exit(3);
process.stdout.write(String(key));
'@
    $tmp = [System.IO.Path]::GetTempFileName() + '.js'
    Set-Content -Path $tmp -Value $nodeScript -Encoding UTF8
    try {
        $key = & node $tmp $dbPath 2>$null
        if ($LASTEXITCODE -eq 0 -and $key) { return $key.Trim() }
    } finally {
        Remove-Item $tmp -Force -ErrorAction SilentlyContinue
    }
    return $null
}

if (-not $ApiKey) {
    $ApiKey = $env:HCAI_API_KEY
}
if (-not $ApiKey) {
    $ApiKey = Get-HcaiApiKeyFromCcSwitch
}
if (-not $ApiKey) {
    Write-Host 'Missing API key. Pass -ApiKey, set HCAI_API_KEY, or configure HCAI in CC Switch.' -ForegroundColor Red
    exit 1
}

$cursorProcs = Get-Process -Name 'Cursor' -ErrorAction SilentlyContinue
if ($cursorProcs) {
    Write-Host 'Cursor is still running. Close all Cursor windows first, then re-run.' -ForegroundColor Yellow
    exit 2
}

$stateDb = Join-Path $env:APPDATA 'Cursor\User\globalStorage\state.vscdb'
if (-not (Test-Path $stateDb)) {
    Write-Host "Cursor state DB not found: $stateDb" -ForegroundColor Red
    exit 3
}

$backup = "$stateDb.bak-hcai-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
Copy-Item $stateDb $backup -Force
Write-Host "Backup: $backup" -ForegroundColor DarkGray

$hcaiModels = @('gpt-5.5', 'gpt-5.4', 'gpt-5.4-mini', 'gpt-5.3-codex')

$nodeScript = @'
const { DatabaseSync } = require('node:sqlite');
const fs = require('fs');

const dbPath = process.argv[2];
const apiKey = process.argv[3];
const baseUrl = process.argv[4];
const models = JSON.parse(process.argv[5]);

const db = new DatabaseSync(dbPath);
const appKey = 'src.vs.platform.reactivestorage.browser.reactiveStorageServiceImpl.persistentStorage.applicationUser';

const row = db.prepare('SELECT value FROM ItemTable WHERE key = ?').get(appKey);
if (!row) {
  console.error('applicationUser row missing');
  process.exit(10);
}

const data = JSON.parse(row.value);
data.openAIBaseUrl = baseUrl;
data.useOpenAIKey = true;
data.availableAPIKeyModels = models;

db.prepare('UPDATE ItemTable SET value = ? WHERE key = ?').run(JSON.stringify(data), appKey);

const keyRow = db.prepare("SELECT value FROM ItemTable WHERE key = 'cursorAuth/openAIKey'").get();
if (keyRow) {
  db.prepare("UPDATE ItemTable SET value = ? WHERE key = 'cursorAuth/openAIKey'").run(apiKey);
} else {
  db.prepare('INSERT INTO ItemTable (key, value) VALUES (?, ?)').run('cursorAuth/openAIKey', apiKey);
}

console.log('OK');
console.log('openAIBaseUrl=' + baseUrl);
console.log('useOpenAIKey=true');
console.log('availableAPIKeyModels=' + models.join(','));
console.log('openAIKey=' + apiKey.slice(0, 10) + '...');
'@

$tmp = [System.IO.Path]::GetTempFileName() + '.js'
Set-Content -Path $tmp -Value $nodeScript -Encoding UTF8
try {
    $modelsJson = ($hcaiModels | ConvertTo-Json -Compress)
    & node $tmp $stateDb $ApiKey $BaseUrl $modelsJson
    if ($LASTEXITCODE -ne 0) {
        Write-Host 'Configuration failed. Restoring backup...' -ForegroundColor Red
        Copy-Item $backup $stateDb -Force
        exit $LASTEXITCODE
    }
} finally {
    Remove-Item $tmp -Force -ErrorAction SilentlyContinue
}

Write-Host ''
Write-Host 'Cursor HCAI BYOK configured.' -ForegroundColor Green
