# One-shot: configure Cursor BYOK -> HCAI (OpenAI-compatible)
# Usage:
#   powershell -File configure-cursor-hcai.ps1 -ApiKey "sk-..."
#   (or set user env HCAI_API_KEY first)

param(
    [Parameter(Mandatory = $false)]
    [string]$ApiKey,
    [string]$BaseUrl = 'https://ai.hctopup.com/v1',
    [switch]$Force
)

$ErrorActionPreference = 'Stop'
$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$env:NODE_NO_WARNINGS = '1'

function Get-HcaiKeyFromCcSwitch {
    $reader = Join-Path $scriptDir '_get-hcai-key.js'
    if (-not (Test-Path $reader)) { return $null }
    try {
        $cfg = node (Join-Path $scriptDir '_list-cc-keys.js') 2>$null | ConvertFrom-Json -ErrorAction SilentlyContinue
    } catch {}
    $rows = @()
    try { $rows = @(node (Join-Path $scriptDir '_list-cc-keys.js') 2>$null | ForEach-Object { $_ | ConvertFrom-Json }) } catch {}
    foreach ($r in $rows) {
        if ($r.id -eq 'hcai-1780471653026' -and $r.tokenPrefix -like 'sk-*') {
            return (node -e "const {DatabaseSync}=require('node:sqlite');const db=new DatabaseSync(process.env.USERPROFILE+'/.cc-switch/cc-switch.db');const row=db.prepare(`"SELECT settings_config FROM providers WHERE id='hcai-1780471653026'`").get();process.stdout.write(JSON.parse(row.settings_config).env.ANTHROPIC_AUTH_TOKEN);")
        }
    }
    return $null
}

if (-not $ApiKey) { $ApiKey = $env:HCAI_API_KEY }
if (-not $ApiKey -or -not $ApiKey.StartsWith('sk-')) {
    Write-Host 'Pass -ApiKey sk-... or set user env HCAI_API_KEY' -ForegroundColor Red
    exit 1
}

$cursorProcs = Get-Process -Name 'Cursor' -ErrorAction SilentlyContinue
if ($cursorProcs -and -not $Force) {
    Write-Host 'Close Cursor completely, then re-run. Or add -Force.' -ForegroundColor Yellow
    exit 2
}

$stateDb = Join-Path $env:APPDATA 'Cursor\User\globalStorage\state.vscdb'
if (-not (Test-Path $stateDb)) {
    Write-Host "Missing: $stateDb" -ForegroundColor Red
    exit 3
}

$backup = "$stateDb.bak-hcai-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
Copy-Item $stateDb $backup -Force
Write-Host "Backup: $backup" -ForegroundColor DarkGray

$fetch = Join-Path $scriptDir '_fetch-hcai-models.js'
$apply = Join-Path $scriptDir 'apply-cursor-hcai.js'
$fixCc = Join-Path $scriptDir 'fix-cc-switch-hcai-key.js'
$verify = Join-Path $scriptDir '_verify-cursor-hcai.js'

try {
    $modelsJson = node $fetch $ApiKey
    if ($LASTEXITCODE -ne 0) { throw "HCAI API test failed" }
    $models = (($modelsJson | ConvertFrom-Json).models) -join ','
    if (-not $models) { throw 'No models returned from HCAI' }

    node $apply $stateDb $ApiKey $BaseUrl $models
    if ($LASTEXITCODE -ne 0) { throw 'Cursor DB update failed' }

    if (Test-Path $fixCc) {
        node $fixCc $ApiKey | Out-Null
    }

    [System.Environment]::SetEnvironmentVariable('HCAI_API_KEY', $ApiKey, 'User')
} catch {
    Write-Host $_.Exception.Message -ForegroundColor Red
    Copy-Item $backup $stateDb -Force
    exit 4
}

Write-Host ''
Write-Host 'Done. Cursor HCAI BYOK configured (Verify step done via API test).' -ForegroundColor Green
Write-Host 'Restart Cursor, then pick gpt-5.5 in Agent (not Auto).'
Write-Host ''
